"""Python extraction with stdlib `ast`. Source is parsed only; repository code is never imported or run."""
from __future__ import annotations

import ast
import warnings

from rw.repo.model import Relation, Symbol

VERSION = "3"
LIMITS = [
    "Dynamic imports (importlib, __import__, imports built from strings) are not extracted.",
    "Calls through getattr, dicts of callables, or other dynamic dispatch are not resolved.",
    "Symbols generated by decorators, metaclasses, exec/eval or runtime assignment are not extracted.",
    "CALLS are resolved by simple name only (local definitions and imported names; attribute calls "
    "keep only the attribute name) and are marked provenance='inferred'.",
    "INHERITS targets are base-class expressions resolved through imports; no MRO computation.",
    "Parameterized base origins (e.g. Base[T]) are static inferences from the subscript value; "
    "__class_getitem__ and runtime inheritance are not evaluated. Bases containing calls or "
    "other unresolved complex expressions are not extracted.",
    "Star imports are recorded as an import of the module; the names they bind are not tracked.",
    "Nested functions/classes inside functions are not emitted as separate symbols.",
    "Files that fail to parse produce an extraction error and only a module symbol.",
]


def module_name(path: str) -> str:
    p = path[:-3] if path.endswith(".py") else path.rsplit(".", 1)[0]
    parts = [x for x in p.split("/") if x]
    if parts and parts[-1] == "__init__" and len(parts) > 1:
        parts = parts[:-1]
    return ".".join(parts)


class PythonAdapter:
    language = "python"
    extensions = (".py", ".pyi")
    version = VERSION
    LIMITS = LIMITS

    def extract(self, path: str, data: bytes):
        from rw.repo.adapters import Extraction
        mod = module_name(path)
        is_pkg = path.endswith("__init__.py")
        extractor = f"python@{self.version}"
        text = data.decode("utf-8", "replace")
        nlines = max(1, text.count("\n") + (0 if text.endswith("\n") else 1))
        ex = Extraction(symbols=[Symbol(mod, "module", 1, nlines)], limits=list(LIMITS))
        try:
            with warnings.catch_warnings():  # e.g. SyntaxWarning for invalid escapes in old sources
                warnings.simplefilter("ignore")
                tree = ast.parse(text, filename=path)
        except (SyntaxError, ValueError) as e:
            ex.errors.append(f"{path}: {type(e).__name__}: {e}")
            return ex

        package = mod if is_pkg else mod.rpartition(".")[0]
        names: dict[str, str] = {}  # local binding -> qualified target
        rels: list[Relation] = []
        relative_targets: dict[str, str] = {}

        def rel(kind, src, tgt, prov):
            relative = None
            for prefix in sorted(relative_targets, key=len, reverse=True):
                if tgt == prefix or tgt.startswith(prefix + "."):
                    relative = relative_targets[prefix] + tgt[len(prefix):]
                    break
            rels.append(Relation(kind, src, tgt, prov, extractor, relative))

        # imports anywhere in the module bind names for resolution
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for a in node.names:
                    rel("IMPORTS", mod, a.name, "parsed")
                    names[a.asname or a.name.split(".")[0]] = a.name if a.asname else a.name.split(".")[0]
            elif isinstance(node, ast.ImportFrom):
                base = node.module or ""
                if node.level:
                    anchor = package.split(".") if package else []
                    anchor = anchor[:len(anchor) - (node.level - 1)] if node.level > 1 else anchor
                    base = ".".join([*anchor, *([base] if base else [])])
                for a in node.names:
                    target = f"{base}.{a.name}" if base and a.name != "*" else (base or a.name)
                    if node.level:
                        suffix = ".".join(x for x in (node.module, None if a.name == "*" else a.name) if x)
                        relative_targets[target] = "." * node.level + suffix
                    if a.name == "*":
                        rel("IMPORTS", mod, base, "parsed")
                        continue
                    rel("IMPORTS", mod, target, "parsed")
                    names[a.asname or a.name] = target

        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                names.setdefault(node.name, f"{mod}.{node.name}")
            # module-level definitions override imports of the same name when defined later
        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                names[node.name] = f"{mod}.{node.name}"

        def dotted(expr) -> str | None:
            if isinstance(expr, ast.Name):
                return names.get(expr.id, expr.id)
            if isinstance(expr, ast.Attribute):
                head = dotted(expr.value)
                return f"{head}.{expr.attr}" if head else None
            return None

        def call_target(func) -> str | None:
            if isinstance(func, ast.Name):
                return names.get(func.id, func.id)
            if isinstance(func, ast.Attribute):
                if isinstance(func.value, ast.Name) and func.value.id in names:
                    return f"{names[func.value.id]}.{func.attr}"
                return func.attr
            return None

        def calls_in(body_nodes, src):
            for stmt in body_nodes:
                for n in ast.walk(stmt):
                    if isinstance(n, ast.Call):
                        t = call_target(n.func)
                        if t:
                            rel("CALLS", src, t, "inferred")

        def visit(nodes, prefix, in_class):
            loose = []
            for node in nodes:
                if isinstance(node, ast.ClassDef):
                    q = f"{prefix}.{node.name}"
                    ex.symbols.append(Symbol(q, "class", node.lineno, node.end_lineno or node.lineno))
                    for b in node.bases:
                        origin, provenance = b, "parsed"
                        while isinstance(origin, ast.Subscript):
                            origin, provenance = origin.value, "inferred"
                        t = dotted(origin)
                        if t:
                            rel("INHERITS", q, t, provenance)
                    visit(node.body, q, True)
                elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    q = f"{prefix}.{node.name}"
                    kind = "method" if in_class else "function"
                    ex.symbols.append(Symbol(q, kind, node.lineno, node.end_lineno or node.lineno))
                    calls_in(node.decorator_list + node.body, q)
                else:
                    loose.append(node)
            calls_in(loose, prefix)

        visit(tree.body, mod, False)
        ex.relations = rels
        return ex
